_FIELDS = (ui.number, ui.input, ui.select, ui.textarea)      # campos con hueco "append" (q-input / q-select)
_TOGGLES = (ui.switch, ui.checkbox)                          # interruptores: icono a continuacion
_TIP = 'max-width="340px" anchor="bottom middle" self="top middle"'


def _label_map(lang: str) -> dict[str, str]:
    """etiqueta visible -> texto de ayuda, en el idioma pedido (claves de TEXT y etiquetas literales)."""
    tx = TEXT.get(lang, TEXT["es"]); hp = HELP.get(lang, HELP["es"])
    out = {}
    for key, txt in hp.items():
        if txt.startswith("@"):
            txt = tx.get(txt[1:], "")
        if not txt:
            continue
        label = tx.get(key, key)                 # clave de i18n o etiqueta literal
        out[str(label)] = txt
    return out


def text_for(label: str, lang: str = "es") -> str | None:
    return _label_map(lang).get(str(label))


def attach(el, txt: str) -> None:
    """Añade el icono (i) con la ayuda al elemento (al final del campo, o justo después si es un interruptor)."""
    if getattr(el, "_help_done", False) or not txt:
        return
    el._help_done = True
    try:
        if isinstance(el, _FIELDS):
            with el.add_slot("append"):
                with ui.icon("info_outline", size="18px").classes("text-grey-6 cursor-help"):
                    ui.tooltip(txt).props(_TIP).classes("text-body2")
        elif getattr(el, "_help_mode", "") == "tooltip":   # casillas en cuadrícula (Salidas): tooltip sobre la propia casilla
            el.tooltip(txt)
        else:                                    # interruptor o casilla: icono a continuación, en el mismo contenedor
            parent = el.parent_slot.parent if el.parent_slot else None
            if parent is None:
                el.tooltip(txt); return
            with parent:
                with ui.icon("info_outline", size="18px").classes("text-grey-6 cursor-help q-ml-xs") as ic:
                    ui.tooltip(txt).props(_TIP).classes("text-body2")
            idx = parent.default_slot.children.index(el)
            ic.move(target_container=parent, target_index=idx + 1)
            ic.bind_visibility_from(el, "visible")   # el icono se oculta con su interruptor (sin (i) huérfanos)
    except Exception:                            # noqa: BLE001  (la ayuda nunca debe romper la página)
        pass


def toggle_help(tg, keys: dict, lang: str = "es"):
    """Icono (i) con su ayuda dentro de cada botón de un ui.toggle: keys = {valor de la opción: clave de HELP}."""
    hp = HELP.get(lang, HELP["es"])
    slots = {}
    for i, v in enumerate(tg._values):
        txt = hp.get(keys.get(v, ""), "")
        if not txt:
            continue
        slots[i] = f"help{i}"
        with tg.add_slot(f"help{i}"):
            with ui.icon("info_outline", size="16px").classes("text-grey-6 cursor-help q-ml-xs"):
                ui.tooltip(txt).props(_TIP).classes("text-body2")
    upd = tg._update_options
    def _update_options():                       # las opciones se regeneran al actualizar: se vuelven a enlazar los slots
        upd()
        for i, name in slots.items():
            tg._props["options"][i]["slot"] = name
    tg._update_options = _update_options
    _update_options(); tg.update()
    return tg


def hint(el, key: str, lang: str = "es"):
    """Ayuda explícita para un campo (por clave de HELP), para los creados fuera del recorrido automático."""
    hp = HELP.get(lang, HELP["es"]).get(key)
    if hp:
        attach(el, TEXT.get(lang, TEXT["es"]).get(hp[1:], "") if hp.startswith("@") else hp)
    return el


def annotate(client, lang: str = "es") -> int:
    """Recorre los elementos del cliente y añade el icono de ayuda a los campos con ayuda conocida. Devuelve cuántos."""
    m = _label_map(lang); n = 0
    for el in list(client.elements.values()):
        if getattr(el, "_help_done", False):
            continue
        if isinstance(el, _FIELDS):
            label = el._props.get("label")
        elif isinstance(el, _TOGGLES):
            label = getattr(el, "text", None)
        else:
            continue
        txt = m.get(str(label)) if label is not None else None
        if txt:
            attach(el, txt); n += 1
    return n
